  const dfs = (node) => {
    if (!node) { vals.push('null'); return; }
    vals.push(node.val);
    dfs(node.left);
    dfs(node.right);
  };
  dfs(root);
  return vals.join(',');
}
function deserialize(data) {
  const vals = data.split(',');
  let i = 0;
  const dfs = () => {
    if (vals[i] === 'null') return i++, null;
    const node = new TreeNode(+vals[i++]);
    node.left = dfs();
    node.right = dfs();
    return node;
  };
  return dfs();
}

