function findMedianSortedArrays(nums1, nums2) {
  const m = nums1.length, n = nums2.length;
  if (m > n) return findMedianSortedArrays(nums2, nums1);
  let l = 0, r = m;
  while (l <= r) {
    const i = (l + r) >> 1, j = (m + n + 1) / 2 - i;
    const left1 = i ? nums1[i - 1] : -Infinity;
    const left2 = j ? nums2[j - 1] : -Infinity;
    const right1 = i < m ? nums1[i] : Infinity;
    const right2 = j < n ? nums2[j] : Infinity;
    if (left1 <= right2 && left2 <= right1)
      return (m + n) % 2
        ? Math.max(left1, left2)
        : (Math.max(left1, left2) + Math.min(right1, right2)) / 2;
    if (left1 > right2) r = i - 1;
    else l = i + 1;
  }
}

