function myPow(x, n) {
  if (n === 0) return 1;
  if (n < 0) { x = 1 / x; n = -n; }
  let res = 1;
  while (n) {
    if (n & 1) res *= x;
    x *= x;
    n >>= 1;
  }
  return res;
}

