function exist(board, word) {
  const m = board.length, n = board[0].length;
  const dfs = (i, j, idx) => {
    if (idx === word.length) return true;
    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] !== word[idx]) return false;
    board[i][j] = '#';
    const found = dfs(i + 1, j, idx + 1) || dfs(i - 1, j, idx + 1) ||
                 dfs(i, j + 1, idx + 1) || dfs(i, j - 1, idx + 1);
    board[i][j] = word[idx];
    return found;
  };
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      if (dfs(i, j, 0)) return true;
  return false;
}

function longestConsecutive(nums) {
  const set = new Set(nums);
  let max = 0;
  for (const num of nums) {
    if (!set.has(num - 1)) {
      let curr = num, len = 1;
      while (set.has(curr + 1)) { curr++; len++; }
      max = Math.max(max, len);
    }
  }
  return max;
}

function partition(s) {
  const res = [];
  const isPal = (l, r) => {
    while (l < r) if (s[l++] !== s[r--]) return false;
    return true;
  };
  const dfs = (idx, curr) => {
    if (idx === s.length) { res.push([...curr]); return; }
    for (let i = idx; i < s.length; i++)
      if (isPal(idx, i)) {
        curr.push(s.slice(idx, i + 1));
        dfs(i + 1, curr);
        curr.pop();
      }
  };
  dfs(0, []);
  return res;
}

function generate(numRows) {
  const res = [];
  for (let i = 0; i < numRows; i++) {
    const row = new Array(i + 1).fill(1);
    for (let j = 1; j < i; j++) row[j] = res[i - 1][j - 1] + res[i - 1][j];
    res.push(row);
  }
  return res;
}

function hammingWeight(n) {
  let count = 0;
  while (n) { n &= n - 1; count++; }
  return count;
}

function singleNumber(nums) {
  let res = 0;
  for (const n of nums) res ^= n;
  return res;
}

