function addTwoNumbers(l1, l2) {
  const dummy = new ListNode(0);
  let curr = dummy, carry = 0;
  while (l1 || l2 || carry) {
    const sum = (l1 ? l1.val : 0) + (l2 ? l2.val : 0) + carry;
    carry = sum / 10 | 0;
    curr.next = new ListNode(sum % 10);
    curr = curr.next;
    l1 = l1 && l1.next;
    l2 = l2 && l2.next;
  }
  return dummy.next;
}

function reverse(x) {
  let rev = 0;
  while (x) {
    rev = rev * 10 + (x % 10);
    x = x / 10 | 0;
    if (rev > 2147483647 || rev < -2147483648) return 0;
  }
  return rev;
}

