class FreqStack {
  constructor() {
    this.freq = new Map();
    this.groups = new Map();
    this.maxFreq = 0;
  }
  push(val) {
    const f = (this.freq.get(val) || 0) + 1;
    this.freq.set(val, f);
    this.maxFreq = Math.max(this.maxFreq, f);
    if (!this.groups.has(f)) this.groups.set(f, []);
    this.groups.get(f).push(val);
  }
  pop() {
    const val = this.groups.get(this.maxFreq).pop();
    this.freq.set(val, this.maxFreq - 1);
    if (!this.groups.get(this.maxFreq).length) this.maxFreq--;
    return val;
  }
}
